using System.Collections.Generic; using UnityEngine;
namespace SkyIsland {public partial class SkyIslandPrototype {
 Transform panelGhost; int panelRotation,panelLevel; bool panelVertical;PanelState panelCandidate;bool panelSnapped;
 readonly Dictionary<string,GameObject> panelObjects=new Dictionary<string,GameObject>();
 void InitPanels(){if(survival.placedPanels==null)survival.placedPanels=new List<PanelState>();if(!PanelRules.Validate(survival.placedPanels,island)){survival.placedPanels.Clear();message="旧板件数据校验未通过，已保留岛屿并清理板件";}foreach(var p in survival.placedPanels)RenderPanel(p);panelGhost=Primitive("Panel preview",PrimitiveType.Cube,Vector3.zero,Vector3.one,Mat("panel preview",new Color(.65f,.9f,.55f))).transform;panelGhost.gameObject.SetActive(false);}
 void RenderPanel(PanelState p){var g=Primitive(p.vertical?"Wood wall":"Wood floor",PrimitiveType.Cube,p.Center,new Vector3(1,.1f,1),Mat("wood panels",new Color(.67f,.45f,.25f)),buildings);g.transform.rotation=p.Orientation;g.AddComponent<BoxCollider>();g.AddComponent<PanelMarker>().State=p;panelObjects.Add(p.Key,g);for(int i=-1;i<=1;i++){var line=Primitive("Plank grain",PrimitiveType.Cube,Vector3.zero,Vector3.one,Mat("grain",new Color(.49f,.31f,.17f)),g.transform);line.transform.localPosition=new Vector3(i*.3f,.505f,0);line.transform.localScale=new Vector3(.015f,.02f,1);}}
 void HidePanelPreview(){if(panelGhost)panelGhost.gameObject.SetActive(false);}
 void PanelInput(Ray ray,bool overUI,bool navigating){HidePanelPreview();if(!buildMode||(mode!=3&&mode!=4))return;
 if(mode==4){if(!overUI&&!navigating&&Input.GetMouseButtonDown(0)&&Physics.Raycast(ray,out var hit,100)){var marker=hit.collider.GetComponentInParent<PanelMarker>();if(marker)RemovePanel(marker.State,6);}return;}
 if(Input.GetKeyDown(KeyCode.Q)){var orientation=new PanelState{vertical=panelVertical,rotation=panelRotation};orientation.RotateNext();panelVertical=orientation.vertical;panelRotation=orientation.rotation;}if(Input.GetKeyDown(KeyCode.PageUp))panelLevel=Mathf.Min(3,panelLevel+1);if(Input.GetKeyDown(KeyCode.PageDown))panelLevel=Mathf.Max(0,panelLevel-1);
 if(overUI||navigating)return;panelSnapped=false;
 if(Physics.Raycast(ray,out var anchorHit,100,~0,QueryTriggerInteraction.Ignore)){var anchor=anchorHit.collider.GetComponentInParent<PanelMarker>();if(anchor){if(!PanelSnap.TrySnap(anchor.State,anchorHit.point,anchorHit.normal,panelVertical,panelRotation,out panelCandidate))return;panelSnapped=true;}}
 if(!panelSnapped){var plane=new Plane(Vector3.up,new Vector3(0,.45f+panelLevel,0));if(!plane.Raycast(ray,out float distance))return;var point=ray.GetPoint(distance);panelCandidate=new PanelState{x=Mathf.RoundToInt(point.x),z=Mathf.RoundToInt(point.z),level=panelLevel,rotation=panelRotation,vertical=panelVertical};}
 bool valid=CanPlacePanel(panelCandidate);panelGhost.gameObject.SetActive(true);panelGhost.position=panelCandidate.Center;panelGhost.localScale=new Vector3(1,.1f,1);panelGhost.rotation=panelCandidate.Orientation;panelGhost.GetComponent<Renderer>().sharedMaterial=valid?Mat("panel good",new Color(.45f,.85f,.5f)):Mat("panel bad",new Color(.88f,.35f,.3f));
 if(Input.GetMouseButtonDown(0)){if(!valid){message="木板不足、重复、无支撑、太远或挡住人物/资源/泉水";return;}survival.panels--;survival.placedPanels.Add(panelCandidate);if(!Save()){survival.placedPanels.Remove(panelCandidate);survival.panels++;return;}RenderPanel(panelCandidate);message="木板已拼接；Q切换楼板和墙壁朝向 / PgUp或Dn层高";}}
 void RemovePanel(PanelState panel,float reach){
  string result=PanelDismantle.Remove(survival,panel,island,avatar.position,reach,Save);
  if(result=="complete"){if(panelObjects.TryGetValue(panel.Key,out var obj)){foreach(var collider in obj.GetComponentsInChildren<Collider>())collider.enabled=false;Destroy(obj);panelObjects.Remove(panel.Key);}message="已拆除，返还木板1";}
  else message=result=="range"?"请靠近木板建筑再拆除":result=="full"?"木板库存已满":result=="support"?"上方仍有依赖板件，请从上往下拆除":result=="standing"?"不能拆除脚下楼板":result=="save-failed"?"保存失败，已保留建筑和库存":"这块木板已不存在";
 }
 bool CanPlacePanel(PanelState p){if(survival.panels<=0||Vector3.Distance(avatar.position,p.Center)>6||!PanelRules.Add(survival.placedPanels,p,island))return false;if(!aboard&&airship&&new Bounds(p.Center,p.Size).Intersects(new Bounds(airship.position,new Vector3(2.5f,1,2.5f))))return false;if(new Bounds(p.Center,p.Size).Intersects(new Bounds(avatar.position,new Vector3(.5f,1.3f,.5f))))return false;if(p.level==0){var cell=Hex.FromWorld(new Vector3(p.x,0,p.z));if(cell.Equals(new Hex(0,0))||island.Workshops.Contains(cell))return false;foreach(var node in resourceNodes)if(node!=null&&new Bounds(p.Center,p.Size).Intersects(node.GetComponent<BoxCollider>().bounds))return false;}return true;}
 bool CanRemovePanelGround(Hex h){foreach(var p in survival.placedPanels)if(Hex.FromWorld(new Vector3(p.x,0,p.z)).Equals(h))return false;return true;}
 void DrawPanelHint(float w){if(buildMode&&(mode==3||mode==4))GUI.Label(new Rect(24,411,425,70),mode==4?"点击板件拆除；上层依赖和脚下楼板受保护":$"木板 {survival.panels} · {(panelVertical?"墙壁":"楼板")} · 第{(panelSnapped&&panelCandidate!=null?panelCandidate.level:panelLevel)}层 · {(panelSnapped?"已吸附边缘":"自由放置")}\n指向板件边缘拼接；Q换朝向 / PgUp或Dn空地层高",small);}
}}
